171	// StringArray is a slices of strings, but also accepts
172	// a single string as a value when JSON unmarshaling,
173	// converting it to a slice of one string.
174	type StringArray []string
175	
176	// UnmarshalJSON satisfies json.Unmarshaler.
177	func (sa *StringArray) UnmarshalJSON(b []byte) error {
178		var jsonObj any
179		err := json.Unmarshal(b, &jsonObj)
180		if err != nil {
181			return err
182		}
183		switch obj := jsonObj.(type) {
184		case string:
185			*sa = StringArray([]string{obj})
186			return nil
187		case []any:
188			s := make([]string, 0, len(obj))
189			for _, v := range obj {
190				value, ok := v.(string)
191				if !ok {
192					return errors.New("unsupported type")
193				}
194				s = append(s, value)
195			}
196			*sa = StringArray(s)
197			return nil
198		}
199		return errors.New("unsupported type")
200	}
