40	// ServerLogConfig describes a server's logging configuration. If
41	// enabled without customization, all requests to this server are
42	// logged to the default logger; logger destinations may be
43	// customized per-request-host.
44	type ServerLogConfig struct {
45		// The default logger name for all logs emitted by this server for
46		// hostnames that are not in the logger_names map.
47		DefaultLoggerName string `json:"default_logger_name,omitempty"`
48	
49		// LoggerNames maps request hostnames to one or more custom logger
50		// names. For example, a mapping of `"example.com": ["example"]` would
51		// cause access logs from requests with a Host of example.com to be
52		// emitted by a logger named "http.log.access.example". If there are
53		// multiple logger names, then the log will be emitted to all of them.
54		// If the logger name is an empty, the default logger is used, i.e.
55		// the logger "http.log.access".
56		//
57		// Keys must be hostnames (without ports), and may contain wildcards
58		// to match subdomains. The value is an array of logger names.
59		//
60		// For backwards compatibility, if the value is a string, it is treated
61		// as a single-element array.
62		LoggerNames map[string]StringArray `json:"logger_names,omitempty"`
63	
64		// By default, all requests to this server will be logged if
65		// access logging is enabled. This field lists the request
66		// hosts for which access logging should be disabled.
67		SkipHosts []string `json:"skip_hosts,omitempty"`
68	
69		// If true, requests to any host not appearing in the
70		// logger_names map will not be logged.
71		SkipUnmappedHosts bool `json:"skip_unmapped_hosts,omitempty"`
72	
73		// If true, credentials that are otherwise omitted, will be logged.
74		// The definition of credentials is defined by https://fetch.spec.whatwg.org/#credentials,
75		// and this includes some request and response headers, i.e `Cookie`,
76		// `Set-Cookie`, `Authorization`, and `Proxy-Authorization`.
77		ShouldLogCredentials bool `json:"should_log_credentials,omitempty"`
78	
79		// Log each individual handler that is invoked.
80		// Requires that the log emit at DEBUG level.
81		//
82		// NOTE: This may log the configuration of your
83		// HTTP handler modules; do not enable this in
84		// insecure contexts when there is sensitive
85		// data in the configuration.
86		//
87		// EXPERIMENTAL: Subject to change or removal.
88		Trace bool `json:"trace,omitempty"`
89	}
