202	// errLogValues inspects err and returns the status code
203	// to use, the error log message, and any extra fields.
204	// If err is a HandlerError, the returned values will
205	// have richer information.
206	func errLogValues(err error) (status int, msg string, fields func() []zapcore.Field) {
207		if handlerErr, ok := errors.AsType[HandlerError](err); ok {
208			status = handlerErr.StatusCode
209			if handlerErr.Err == nil {
210				msg = err.Error()
211			} else {
212				msg = handlerErr.Err.Error()
213			}
214			fields = func() []zapcore.Field {
215				return []zapcore.Field{
216					zap.Int("status", handlerErr.StatusCode),
217					zap.String("err_id", handlerErr.ID),
218					zap.String("err_trace", handlerErr.Trace),
219				}
220			}
221			return status, msg, fields
222		}
223		fields = func() []zapcore.Field {
224			return []zapcore.Field{
225				zap.Error(err),
226			}
227		}
228		status = http.StatusInternalServerError
229		msg = err.Error()
230		return status, msg, fields
231	}
232	
233	// ExtraLogFields is a list of extra fields to log with every request.
234	type ExtraLogFields struct {
235		fields   []zapcore.Field
236		handlers sync.Map
237	}
238	
239	// Add adds a field to the list of extra fields to log.
240	func (e *ExtraLogFields) Add(field zap.Field) {
241		e.handlers.Clear()
242		e.fields = append(e.fields, field)
243	}
244	
245	// Set sets a field in the list of extra fields to log.
246	// If the field already exists, it is replaced.
247	func (e *ExtraLogFields) Set(field zap.Field) {
248		e.handlers.Clear()
249	
250		for i := range e.fields {
251			if e.fields[i].Key == field.Key {
252				e.fields[i] = field
253				return
254			}
255		}
256		e.fields = append(e.fields, field)
257	}
258	
259	func (e *ExtraLogFields) getSloggerHandler(handler *extraFieldsSlogHandler) (h slog.Handler) {
260		if existing, ok := e.handlers.Load(handler); ok {
261			return existing.(slog.Handler)
262		}
263	
264		if handler.moduleID == "" {
265			h = zapslog.NewHandler(handler.core.With(e.fields))
266		} else {
267			h = zapslog.NewHandler(handler.core.With(e.fields), zapslog.WithName(handler.moduleID))
268		}
269	
270		if handler.group != "" {
271			h = h.WithGroup(handler.group)
272		}
273		if handler.attrs != nil {
274			h = h.WithAttrs(handler.attrs)
275		}
276	
277		e.handlers.Store(handler, h)
278	
279		return h
280	}
