282	const (
283		// Variable name used to indicate that this request
284		// should be omitted from the access logs
285		LogSkipVar string = "log_skip"
286	
287		// For adding additional fields to the access logs
288		ExtraLogFieldsCtxKey caddy.CtxKey = "extra_log_fields"
289	
290		// Variable name used to indicate the logger to be used
291		AccessLoggerNameVarKey string = "access_logger_names"
292	)
293	
294	type extraFieldsSlogHandler struct {
295		defaultHandler slog.Handler
296		core           zapcore.Core
297		moduleID       string
298		group          string
299		attrs          []slog.Attr
300	}
301	
302	func (e *extraFieldsSlogHandler) Enabled(ctx context.Context, level slog.Level) bool {
303		return e.defaultHandler.Enabled(ctx, level)
304	}
305	
306	func (e *extraFieldsSlogHandler) Handle(ctx context.Context, record slog.Record) error {
307		if elf, ok := ctx.Value(ExtraLogFieldsCtxKey).(*ExtraLogFields); ok {
308			return elf.getSloggerHandler(e).Handle(ctx, record)
309		}
310	
311		return e.defaultHandler.Handle(ctx, record)
312	}
313	
314	func (e *extraFieldsSlogHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
315		return &extraFieldsSlogHandler{
316			e.defaultHandler.WithAttrs(attrs),
317			e.core,
318			e.moduleID,
319			e.group,
320			append(e.attrs, attrs...),
321		}
322	}
323	
324	func (e *extraFieldsSlogHandler) WithGroup(name string) slog.Handler {
325		return &extraFieldsSlogHandler{
326			e.defaultHandler.WithGroup(name),
327			e.core,
328			e.moduleID,
329			name,
330			e.attrs,
331		}
332	}
