218				t.Fatalf("failed to set read deadline: %v", err)
219			}
220			b := make([]byte, len(msg))
221			if _, err := io.ReadFull(conn, b); err != nil {
222				t.Fatalf("failed to read: %v", err)
223			}
224			if got, want := string(b), msg; got != want {
225				t.Fatalf("got %#q, want %#q", got, want)
226			}
227		}
