229		mustReadEOF := func(t *testing.T, conn *net.TCPConn) {
230			t.Helper()
231			if err := conn.SetReadDeadline(time.Now().Add(readTimeout)); err != nil {
232				t.Fatalf("failed to set read deadline: %v", err)
233			}
234			b := make([]byte, 1)
235			if _, err := conn.Read(b); !errors.Is(err, io.EOF) {
236				t.Fatalf("read after peer half-close: got %v, want EOF", err)
237			}
238		}
239	
240		mustWrite := func(t *testing.T, conn *net.TCPConn, msg string) {
241			t.Helper()
242			if _, err := conn.Write([]byte(msg)); err != nil {
243				t.Fatalf("failed to write: %v", err)
244			}
245		}
