326			Method: "PUT",
327			Body:   io.NopCloser(r),
328			URL: &url.URL{
329				Scheme: "https",
330				Host:   "127.0.0.1:9443",
331				Path:   "/tov2ray",
332			},
333			Proto:      "HTTP/2",
334			ProtoMajor: 2,
335			ProtoMinor: 0,
336			Header:     make(http.Header),
337		}
338		// underlying transport will automatically add gzip
339		// req.Header.Set("Accept-Encoding", "gzip")
340		go func() {
341			fmt.Fprint(w, expectedBody)
342			w.Close()
343		}()
344		resp := tester.AssertResponseCode(req, http.StatusOK)
345		if resp.StatusCode != http.StatusOK {
346			return
347		}
348	
349		defer resp.Body.Close()
350		bytes, err := io.ReadAll(resp.Body)
351		if err != nil {
352			t.Fatalf("unable to read the response body %s", err)
353		}
354	
355		body := string(bytes)
356	
357		if body != expectedBody {
