67	// CaddyModule returns the Caddy module information.
68	//
69	// EXPERIMENTAL: Subject to change or removal.
70	func (Intercept) CaddyModule() caddy.ModuleInfo {
71		return caddy.ModuleInfo{
72			ID:  "http.handlers.intercept",
73			New: func() caddy.Module { return new(Intercept) },
74		}
75	}
