1	package caddyhttp
2	
3	import (
4		"bytes"
5		"io"
6		"net/http"
7		"strings"
8		"testing"
9	)
10	
11	type responseWriterSpy interface {
12		http.ResponseWriter
13		Written() string
14		CalledReadFrom() bool
15	}
16	
17	var (
18		_ responseWriterSpy = (*baseRespWriter)(nil)
19		_ responseWriterSpy = (*readFromRespWriter)(nil)
20	)
21	
22	// a barebones http.ResponseWriter mock
23	type baseRespWriter []byte
24	
25	func (brw *baseRespWriter) Write(d []byte) (int, error) {
26		*brw = append(*brw, d...)
27		return len(d), nil
28	}
29	func (brw *baseRespWriter) Header() http.Header        { return nil }
30	func (brw *baseRespWriter) WriteHeader(statusCode int) {}
31	func (brw *baseRespWriter) Written() string            { return string(*brw) }
32	func (brw *baseRespWriter) CalledReadFrom() bool       { return false }
33	
34	// an http.ResponseWriter mock that supports ReadFrom
35	type readFromRespWriter struct {
36		baseRespWriter
37		called bool
38	}
39	
40	func (rf *readFromRespWriter) ReadFrom(r io.Reader) (int64, error) {
41		rf.called = true
42		return io.Copy(&rf.baseRespWriter, r)
43	}
44	
45	func (rf *readFromRespWriter) CalledReadFrom() bool { return rf.called }
46	
47	func TestResponseWriterWrapperReadFrom(t *testing.T) {
48		tests := map[string]struct {
49			responseWriter responseWriterSpy
50			wantReadFrom   bool
51		}{
52			"no ReadFrom": {
53				responseWriter: &baseRespWriter{},
54				wantReadFrom:   false,
55			},
56			"has ReadFrom": {
57				responseWriter: &readFromRespWriter{},
58				wantReadFrom:   true,
59			},
60		}
61		for name, tt := range tests {
62			t.Run(name, func(t *testing.T) {
63				// what we expect middlewares to do:
64				type myWrapper struct {
65					*ResponseWriterWrapper
66				}
67	
68				wrapped := myWrapper{
69					ResponseWriterWrapper: &ResponseWriterWrapper{ResponseWriter: tt.responseWriter},
70				}
71	
72				const srcData = "boo!"
73				// hides everything but Read, since strings.Reader implements WriteTo it would
74				// take precedence over our ReadFrom.
75				src := struct{ io.Reader }{strings.NewReader(srcData)}
76	
77				if _, err := io.Copy(wrapped, src); err != nil {
78					t.Errorf("%s: Copy() err = %v", name, err)
79				}
80	
81				if got := tt.responseWriter.Written(); got != srcData {
82					t.Errorf("%s: data = %q, want %q", name, got, srcData)
83				}
84	
85				if tt.responseWriter.CalledReadFrom() != tt.wantReadFrom {
86					if tt.wantReadFrom {
87						t.Errorf("%s: ReadFrom() should have been called", name)
88					} else {
89						t.Errorf("%s: ReadFrom() should not have been called", name)
90					}
91				}
92			})
93		}
94	}
95	
96	func TestResponseWriterWrapperUnwrap(t *testing.T) {
97		w := &ResponseWriterWrapper{&baseRespWriter{}}
98	
99		if _, ok := w.Unwrap().(*baseRespWriter); !ok {
100			t.Errorf("Unwrap() doesn't return the underlying ResponseWriter")
101		}
102	}
103	
104	func TestResponseRecorderReadFrom(t *testing.T) {
105		tests := map[string]struct {
106			responseWriter responseWriterSpy
107			shouldBuffer   bool
108			wantReadFrom   bool
109		}{
110			"buffered plain": {
111				responseWriter: &baseRespWriter{},
112				shouldBuffer:   true,
113				wantReadFrom:   false,
114			},
115			"streamed plain": {
116				responseWriter: &baseRespWriter{},
117				shouldBuffer:   false,
118				wantReadFrom:   false,
119			},
120			"buffered ReadFrom": {
121				responseWriter: &readFromRespWriter{},
122				shouldBuffer:   true,
123				wantReadFrom:   false,
124			},
125			"streamed ReadFrom": {
126				responseWriter: &readFromRespWriter{},
127				shouldBuffer:   false,
128				wantReadFrom:   true,
129			},
130		}
131		for name, tt := range tests {
132			t.Run(name, func(t *testing.T) {
133				var buf bytes.Buffer
134	
135				rr := NewResponseRecorder(tt.responseWriter, &buf, func(status int, header http.Header) bool {
136					return tt.shouldBuffer
137				})
138	
139				const srcData = "boo!"
140				// hides everything but Read, since strings.Reader implements WriteTo it would
141				// take precedence over our ReadFrom.
142				src := struct{ io.Reader }{strings.NewReader(srcData)}
143	
144				if _, err := io.Copy(rr, src); err != nil {
145					t.Errorf("Copy() err = %v", err)
146				}
147	
148				wantStreamed := srcData
149				wantBuffered := ""
150				if tt.shouldBuffer {
151					wantStreamed = ""
152					wantBuffered = srcData
153				}
154	
155				if got := tt.responseWriter.Written(); got != wantStreamed {
156					t.Errorf("streamed data = %q, want %q", got, wantStreamed)
157				}
158				if got := buf.String(); got != wantBuffered {
159					t.Errorf("buffered data = %q, want %q", got, wantBuffered)
160				}
161	
162				if tt.responseWriter.CalledReadFrom() != tt.wantReadFrom {
163					if tt.wantReadFrom {
164						t.Errorf("ReadFrom() should have been called")
165					} else {
166						t.Errorf("ReadFrom() should not have been called")
167					}
168				}
169			})
