		"level":       {options: "level loud", want: "level"},
	} {
		t.Run(name, func(t *testing.T) {
			caddytest.AssertLoadError(t, streamGlobalOptions+`
			localhost:9080 {
				reverse_proxy 127.0.0.1:9081 {
					stream_logs {
						`+tc.options+`
					}
				}
			}`, "caddyfile", tc.want)
		})
	}
