// HTTP/2 extended CONNECT (RFC 8441) is turned into an upgrade of the
// backend connection.
func TestStreamExtendedConnectH2(t *testing.T) {
	for name, options := range map[string]string{
		"default":  "",
		"detached": "stream_detached",
	} {
		t.Run(name, func(t *testing.T) {
			newUpgradeBackend(t, "127.0.0.1:9081")
			tester := caddytest.NewTester(t)
			tester.InitServer(streamGlobalOptions+`
			localhost:9443 {
				encode gzip
				reverse_proxy 127.0.0.1:9081 {
					`+options+`
				}
			}`, "caddyfile")

			tr := &http2.Transport{
				DialTLSContext: func(_ context_, _, _ string, _ *tls.Config) (net.Conn, error) {
					return tls.Dial("tcp", "127.0.0.1:9443", &tls.Config{
						InsecureSkipVerify: true, //nolint:gosec
						ServerName:         "localhost",
						NextProtos:         []string{"h2"},
					})
				},
			}
			defer tr.CloseIdleConnections()

			pr, pw := io.Pipe()
			defer pw.Close()
			req, err := http.NewRequest(http.MethodConnect, "https://localhost:9443/ws", pr)
			if err != nil {
				t.Fatal(err)
			}
			req.Header.Set(":protocol", "websocket")
			req.Header.Set("Sec-WebSocket-Version", "13")

			resp, err := tr.RoundTrip(req)
			if err != nil {
				t.Fatalf("extended CONNECT failed: %v", err)
			}
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("status = %d, want 200", resp.StatusCode)
			}
			if resp.ProtoMajor != 2 {
				t.Fatalf("protocol = %s, want HTTP/2", resp.Proto)
			}

			for _, msg := range []string{"hello over h2", "and again"} {
				if _, err := io.WriteString(pw, msg); err != nil {
					t.Fatalf("failed to write to the stream: %v", err)
				}
				got := make([]byte, len(msg))
				done := make(chan error, 1)
				go func() {
					_, err := io.ReadFull(resp.Body, got)
					done <- err
				}()
				select {
				case err := <-done:
					if err != nil {
						t.Fatalf("failed to read from the stream: %v", err)
					}
				case <-time.After(streamTestTimeout):
					t.Fatal("timed out reading from the stream")
				}
				if string(got) != msg {
					t.Fatalf("echo = %q, want %q", got, msg)
				}
			}
		})
	}
}

